// Rules engine: deterministic classification (~60% of items)
// Returns { category, confidence } — if confidence >= 0.85, skip Haiku

const item = $input.first().json;
const titleLower = (item.title || '').toLowerCase();
const urlLower = (item.source_url || '').toLowerCase();
const slug = item.source_slug || '';

let category = 'opinion';
let confidence = 0.40;

// Research papers
if (urlLower.includes('arxiv.org') || slug === 'huggingface-papers' ||
    titleLower.includes(' paper') || titleLower.includes('we propose') ||
    titleLower.includes('survey of') || titleLower.includes('we present')) {
  category = 'research_paper'; confidence = 0.92;
}
// Model releases from high-authority sources
else if (['openai-blog','anthropic-blog','deepmind-blog','google-ai-blog','meta-ai-blog','mistral-blog'].includes(slug)) {
  const modelWords = ['gpt-','claude-','gemini ','llama ','mistral-','releases model','new model','model release','launches model',' api available','new api'];
  if (modelWords.some(k => titleLower.includes(k))) {
    category = 'model_release'; confidence = 0.94;
  } else {
    category = 'tool_launch'; confidence = 0.75;
  }
}
// Tools / open source
else if (slug === 'github-trending' || slug === 'producthunt-ai' ||
         urlLower.includes('github.com') || titleLower.includes('open source') ||
         titleLower.includes(' launches ') || titleLower.includes(' introduces ')) {
  category = 'tool_launch'; confidence = 0.85;
}
// Funding
else {
  const fundingWords = ['raises','funding','series a','series b','series c','seed round','valuation','investment'];
  const fundingMatches = fundingWords.filter(k => titleLower.includes(k));
  if (fundingMatches.length >= 2) {
    category = 'funding'; confidence = 0.90;
  }
  // Security
  else {
    const secWords = ['vulnerability','jailbreak','attack','exploit','breach','safety','alignment','red team','adversarial'];
    if (secWords.some(k => titleLower.includes(k))) {
      category = 'security'; confidence = 0.88;
    }
    // Tutorial
    else if (titleLower.startsWith('how to') || titleLower.startsWith('building') ||
             titleLower.includes('tutorial') || titleLower.includes('guide to')) {
      category = 'tutorial'; confidence = 0.87;
    }
    // Regulation
    else {
      const regWords = ['regulation','policy','law','ban','eu ai act','ftc','nist','compliance','govern'];
      if (regWords.some(k => titleLower.includes(k))) {
        category = 'regulation'; confidence = 0.86;
      }
    }
  }
}

return [{ json: { ...item, rules_category: category, rules_confidence: confidence } }];

// Merge classification result and compute final priority score
const item = $('Rules Engine').first().json;
const fromRules = $('Rules Confident?').first()?.json?.rules_confidence >= 0.85;

let category, prioritySignal, classificationMethod;

if (fromRules) {
  category = item.rules_category;
  prioritySignal = 0; // Not used from rules; computed below
  classificationMethod = 'rules';
} else {
  const haikusResponse = $('Haiku Classification').first().json;
  const haikusText = haikusResponse.content?.[0]?.text || '{}';
  let parsed;
  try { parsed = JSON.parse(haikusText); } catch { parsed = {}; }
  category = parsed.category || item.rules_category || 'opinion';
  prioritySignal = parsed.priority_signal || 40;
  classificationMethod = 'haiku';
}

// Cross-coverage component: each additional source adds 5 points, cap 25
const itemCount = item.item_count || 1;
const scoreCrossCoverage = Math.min(25, (itemCount - 1) * 5);

// Final priority score (all 5 components)
const scoreSourceAuthority = item.score_source_authority || 20;
const scoreFreshness = item.score_freshness || 0;
const scoreEngagement = 0; // Updated later when engagement signals arrive
const scoreAuthorAuthority = 0; // Updated later via author registry lookup

const priorityScore = Math.min(100, Math.max(0,
  scoreSourceAuthority + scoreCrossCoverage + scoreFreshness +
  scoreEngagement + scoreAuthorAuthority
));

return [{ json: {
  item_id: item.id,
  category,
  priority_score: priorityScore,
  score_source_authority: scoreSourceAuthority,
  score_cross_coverage: scoreCrossCoverage,
  score_freshness: scoreFreshness,
  score_engagement: scoreEngagement,
  score_author_authority: scoreAuthorAuthority,
  classification_method: classificationMethod
}}];
